window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[254]={"id":"254","numero":254,"titre":"Besoins nutritionnels de la femme enceinte","objectifs":[{"id":"254-1","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les besoins nutritionnels de la femme enceinte","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-brown_bg\">grossesse</span></span> <strong>n'impose pas de « manger pour deux »</strong> : il ne faut <span>pas augmenter volontairement les apports</span>. Les besoins énergétiques n'<span class=\"nc-green nc-bold\">augmentent</span> que modérément, et de façon progressive selon le trimestre.</p>\n      <div class=\"callout callout-danger\"><strong>Apport énergétique global : <span>1600 kcal/j minimum</span>.</strong> En dessous de ce seuil, production de <span>corps cétoniques</span> — délétère pour le <span>développement cérébral du fœtus</span> (risque de <span>RCIU</span> et de <span><span class=\"nc-red nc-bold\">faible poids de naissance</span></span>).</div>\n      <p><strong>Surcoût énergétique par trimestre</strong> (à ne pas rechercher activement, l'appétit s'adapte spontanément) :</p>\n      <table>\n        <thead><tr><th>Trimestre</th><th>Surcoût énergétique</th></tr></thead>\n        <tbody>\n          <tr><td><span><strong>T1</strong></span></td><td><span>+ 70 kcal/j</span> (faible)</td></tr>\n          <tr><td><span><strong>T2</strong></span></td><td><span>+ 260 kcal/j</span></td></tr>\n          <tr><td><span><strong>T3</strong></span></td><td><span>+ 500 kcal/j</span> (maximal)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Répartition des macronutriments</strong> — en proportion de l'apport énergétique total, elle reste <strong>identique à la population générale</strong> (seule exception : seuil minimal des protéines au T3 = <span>12 %</span>).</p>\n      <ul>\n        <li><span>Glucides</span> (<span>50-55 %</span>) : besoins ↗ de <span>130 → 175 g/j</span></li>\n        <li><span>Protides</span> (<span>15-20 %</span>) : besoins ↗ jusqu'à <span>70 g/j</span></li>\n        <li><span>Lipides</span> (<span>30 %</span>) : <strong>pas de modification</strong> des besoins</li>\n      </ul>\n      <p><strong>Une alimentation variée et fractionnée</strong></p>\n      <ul>\n        <li><span>Produits laitiers</span> (calcium), <span>fruits et légumes frais</span> (vitamines)</li>\n        <li>Repas <strong>fractionnés</strong> : <span>3 à 5×/jour</span></li>\n        <li><span>Poisson</span> <span>3×/semaine</span> — éviter espadon et maquereau (<span>métaux lourds</span>), éviter saumon sauvage, <strong>varier les lieux d'approvisionnement</strong></li>\n        <li>Privilégier les aliments riches en <span>B9</span>, <span>β-carotène</span> et <span>vitamine C</span></li>\n        <li>Limiter le <span><span class=\"nc-blue_bg\">soja</span></span> (<strong><span>≤ 1/jour</span></strong>) ; <span class=\"nc-red nc-bold\">margarine enrichie</span> en phytostérols <strong>déconseillée</strong></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Apports hydriques.</strong> Besoins <strong>augmentés</strong> : <span><span class=\"nc-pink nc-bold\">2,3-2,5 L</span>/j</span>. <span>CI absolue à l'<span class=\"nc-red nc-bold\">alcool</span>.</span> Pas de <span class=\"nc-red nc-bold\">boissons gazeuses</span>/sodas ; éviter les <span class=\"nc-red nc-bold\">boissons riches en sel</span> ; limiter les <span class=\"nc-red\">excitants</span> (<span><span class=\"nc-red nc-bold\">café</span>, <span class=\"nc-red nc-bold\">thé</span></span>).</div>\n      <div class=\"callout callout-warn\"><strong>Les 1000 premiers jours (programmation).</strong> De la <strong>conception à<span> 2 ans</span></strong> = fenêtre critique de vulnérabilité à l'environnement (<span><span class=\"nc-orange\">origine développementale des maladies</span></span>). <span class=\"nc-orange_bg\">Dénutrition</span>, malnutrition ou surnutrition maternelles ↗ le risque d'<span><span class=\"nc-orange_bg\">obésité</span></span>, de <span>diabète</span> et de <span>maladie cardiovasculaire</span> chez l'enfant à l'âge adulte (mécanismes <span>épigénétiques</span>).</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":0},{"id":"254-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la prise de poids attendue pendant la grossesse","contenu":"<div class=\"notion-course\"><p>La prise de poids associe <span>poids du <span class=\"nc-green nc-bold\">fœtus</span></span>, <span><span class=\"nc-green nc-bold\">placenta</span></span>, <span><span class=\"nc-green nc-bold\">liquide amniotique</span></span> et <span>accumulation de graisse</span> maternelle. Elle est <strong>faible au T1</strong>, puis <strong>marquée aux T2 et T3</strong>, et <strong>influencée par l'IMC pré-<span><span class=\"nc-brown_bg\">grossesse</span></span></strong>. En moyenne <span>≈ <span class=\"nc-pink nc-bold\">13 kg</span></span> (variations possibles : <span>œdèmes</span>, durée de <span class=\"nc-brown_bg\">grossesse</span>, gémellité).</p>\n      <div class=\"callout callout-info\"><strong>Repères pratiques.</strong> <span>≈ 1 kg/mois</span> du T1 au T3, et <span>500 g/semaine</span> au T3.</div>\n      <p><strong>Gain pondéral recommandé selon l'IMC pré-conceptionnel</strong></p>\n      <table>\n        <thead><tr><th>IMC pré-conceptionnel</th><th>Gain total recommandé</th><th>Taux moyen T2-T3</th></tr></thead>\n        <tbody>\n          <tr><td><span>Maigreur</span> (&lt; 18,5)</td><td><span>12,5 – 18 kg</span></td><td><span>0,5 kg/sem</span></td></tr>\n          <tr><td><span>Normal</span> (18,5 – 24,9)</td><td><span>11,5 – 16 kg</span></td><td><span>0,4 kg/sem</span></td></tr>\n          <tr><td><span>Surpoids</span> (25 – 29,9)</td><td><span>7 – 11,5 kg</span></td><td><span>0,3 kg/sem</span></td></tr>\n          <tr><td><span>Obésité</span> (<span>≥ 30</span>)</td><td><span>5 – 9 kg</span></td><td><span>0,2 kg/sem</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"nc-red_bg\">Prise de poids excessive</span>.</strong> Risque de <span><span class=\"nc-orange_bg\">diabète gestationnel</span></span>, de <span><span class=\"nc-red nc-bold\">HTA gravidique</span></span>, de <span><span class=\"nc-red nc-bold\">macrosomie</span></span> et de <span><span class=\"nc-red nc-bold\">césarienne</span></span> (surcharge pondérale).</div>\n      <div class=\"callout callout-warn\"><strong><span class=\"nc-red_bg\">Prise de poids insuffisante</span>.</strong> Risque de <span>menace d'<span class=\"nc-red nc-bold\">accouchement prématuré</span> (MAP)</span> et de <span><span class=\"nc-red nc-bold\">faible poids de naissance</span></span>.</div>\n      <p class=\"muted\" style=\"margin:6px 0 0\"><em>Un poids de naissance &lt; <span>2500 g</span> ou &gt; <span>4000 g</span> est un FDR ultérieur d'<span><span class=\"nc-orange_bg\">obésité</span></span> et de <span><span class=\"nc-orange_bg\">syndrome métabolique</span></span> chez l'enfant.</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":0},{"id":"254-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la prévention du spina-bifida","contenu":"<div class=\"notion-course\"><ul><li>La fermeture du tube neural se déroule très tôt, pendant les premières semaines après la conception, souvent avant la découverte de la grossesse. La prévention doit donc commencer avant la conception.</li><li>Acide folique 400 µg/j en prévention courante : idéalement au moins quatre semaines avant la conception et jusqu’à douze SA. Une alimentation riche en folates complète, sans remplacer, cette supplémentation.</li><li>Chez certaines femmes à haut risque, notamment antécédent d’anomalie de fermeture du tube neural, une dose élevée sur prescription est indiquée ; vérifier les facteurs et le schéma avec l’équipe.</li><li>Un traitement antiépileptique potentiellement tératogène nécessite une consultation préconceptionnelle ; ne pas l’arrêter brutalement et ne pas considérer que les folates annulent sa tératogénicité.</li></ul><figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 560 156\" role=\"img\" aria-label=\"Frise temporelle de la prévention du spina-bifida : supplémentation en folates 0,4 mg par jour débutée 28 jours avant la conception, conception, fermeture du tube neural avant la 3e semaine soit avant que la grossesse ne soit connue, fin de la supplémentation systématique à 10 SA. En cas de haut risque (épilepsie sous anticonvulsivants, surpoids avec IMC supérieur à 28, antécédent de dysraphie), dose élevée de 4 à 5 mg par jour avec vitamines B6 et B12.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"18\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Prévention du spina-bifida — supplémentation en <span>folates</span></text>\n          <rect class=\"fb-ok\" x=\"8\" y=\"42\" width=\"125\" height=\"64\" rx=\"6\"></rect>\n          <text class=\"tx-ok\" x=\"70.5\" y=\"60\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">−28 j</text>\n          <text class=\"tx-ok\" x=\"70.5\" y=\"76\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">Folates <span>0,4 mg</span>/j</text>\n          <text class=\"tx-ok\" x=\"70.5\" y=\"91\" text-anchor=\"middle\" font-size=\"7.5\">(pré-conception)</text>\n          <rect class=\"fb-blue\" x=\"147\" y=\"42\" width=\"125\" height=\"64\" rx=\"6\"></rect>\n          <text class=\"tx-blue\" x=\"209.5\" y=\"60\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\"><span>J0</span></text>\n          <text class=\"tx-blue\" x=\"209.5\" y=\"78\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">Conception</text>\n          <rect class=\"fb-amber\" x=\"286\" y=\"42\" width=\"125\" height=\"64\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"348.5\" y=\"60\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">&lt; S3</text>\n          <text class=\"tx-amber\" x=\"348.5\" y=\"76\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">Fermeture tube neural</text>\n          <text class=\"tx-amber\" x=\"348.5\" y=\"91\" text-anchor=\"middle\" font-size=\"7.5\">avant <span>grossesse</span> connue</text>\n          <rect class=\"fb-ok\" x=\"425\" y=\"42\" width=\"125\" height=\"64\" rx=\"6\"></rect>\n          <text class=\"tx-ok\" x=\"487.5\" y=\"60\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">12 SA</text>\n          <text class=\"tx-ok\" x=\"487.5\" y=\"76\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">Fin supplémentation</text>\n          <text class=\"tx-ok\" x=\"487.5\" y=\"91\" text-anchor=\"middle\" font-size=\"7.5\">systématique (LiSA)</text>\n          <line class=\"ln\" x1=\"135\" y1=\"74\" x2=\"144\" y2=\"74\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"147,74 141,70 141,78\"></polygon>\n          <line class=\"ln\" x1=\"274\" y1=\"74\" x2=\"283\" y2=\"74\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"286,74 280,70 280,78\"></polygon>\n          <line class=\"ln\" x1=\"413\" y1=\"74\" x2=\"422\" y2=\"74\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"425,74 419,70 419,78\"></polygon>\n          <rect class=\"fb-amber\" x=\"8\" y=\"118\" width=\"544\" height=\"32\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"280\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"600\">Haut risque (épilepsie · surpoids IMC &gt; 28 · ATCD dysraphie)</text>\n          <text class=\"tx-amber\" x=\"280\" y=\"145\" text-anchor=\"middle\" font-size=\"8.5\">→<span> 4 à 5 mg</span>/j (dose × 10) + vitamines B6/B12</text>\n        </svg>\n        <figcaption>La fenêtre de supplémentation encadre la conception : commencer <strong>avant</strong> la grossesse (tube neural fermé dès S3) ; dose × 10 si haut risque.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":0},{"id":"254-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les populations à risque nutritionnel pendant la grossesse","contenu":"<div class=\"notion-course\"><p>Repérer ces situations à l'interrogatoire permet de <strong>cibler la <span>surveillance</span> et les supplémentations</strong>. Les axes prioritaires de carence à surveiller sont : <span>fer</span>, <span>acide folique</span>, <span>vitamine D</span>, <span>calcium</span>, <span><span class=\"nc-red_bg nc-bold\">iode</span></span> et le <span>risque infectieux</span>.</p>\n      <p><strong><span>Facteurs de risque</span> nutritionnel</strong></p>\n      <ul>\n        <li><span>Adolescentes</span> (croissance non terminée)</li>\n        <li><span>Bas niveau socio-économique et éducatif</span>, précarité</li>\n        <li><span><span class=\"nc-green nc-bold\">Grossesses rapprochées</span></span></li>\n        <li><span>Grossesses multiples</span></li>\n        <li><span>Intoxication alcoolo-tabagique</span>, toxicomanie</li>\n        <li><span>ATCD d'anomalie de fermeture du tube neural</span> ou de fente labio-palatine ; maladies chroniques</li>\n        <li><span>Régimes restrictifs, déséquilibrés</span> (végétarien/végétalien), <span>TCA</span></li>\n        <li><span>Excès pondéral</span>, <span>diabète</span></li>\n      </ul>\n      <p><strong>Situations spécifiques nécessitant une adaptation</strong></p>\n      <table>\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><span><strong>Vomissements du T1</strong></span></td><td><strong>Fractionner</strong> les repas</td></tr>\n          <tr><td><span><strong><span class=\"nc-orange_bg\">Diabète gestationnel</span></strong></span></td><td>Manger équilibré, <span>sans régime restrictif</span></td></tr>\n          <tr><td><span><strong>ATCD chirurgie bariatrique</strong></span></td><td>Risque de <span>carences</span> — <span>surveillance</span> ++</td></tr>\n          <tr><td><span><strong>Obésité</strong></span></td><td>Risque de carences en <span>micronutriments</span></td></tr>\n          <tr><td><span><strong>Adolescente</strong></span> (croissance non finie)</td><td>↗ perte osseuse (<span>grossesse</span> + allaitement) → <strong>compensation calcique</strong></td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":0},{"id":"254-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prévention de la carence en fer, en vitamine D et en calcium","contenu":"<div class=\"notion-course\"><div class=\"callout callout-info\"><strong>Principe clé.</strong> Sur ces trois micronutriments, <strong>une seule supplémentation est systématique : la <span>vitamine D</span> au T3</strong>. Le <span><span class=\"nc-blue_bg\">fer</span></span> et le <span>calcium</span> ne se supplémentent <span>qu'en cas de carence avérée</span> ; le calcium reste couvert par l'alimentation.</div>\n      <table>\n        <thead><tr><th>Micronutriment</th><th><span>Physiopathologie</span> &amp; risques</th><th>Prévention / traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span><strong>Fer</strong></span><br><span>supplémentation NON systématique</span></td>\n            <td>\n              Besoins totaux ≈ <span>1000 mg</span> : <span>30 %</span> pour le fœtus (développement neuro), <span>70 %</span> pour le <span class=\"nc-green nc-bold\">placenta</span> et la <span>masse</span> globulaire maternelle ; ↗ absorption intestinale pour compenser.\n              Carence : <span>25 %</span> des femmes enceintes (pays développés), <span>50 %</span> dans les PED.\n              FDR : <span class=\"nc-brown_bg\">grossesses</span> gémellaires/<span class=\"nc-brown_bg nc-bold\">rapprochées</span>, <span class=\"nc-orange_bg\">ATCD de carence martiale</span>, <span class=\"nc-orange_bg\">régime végétarien</span>, <span class=\"nc-orange_bg\">dénutrition</span>, précarité.\n              Risque : <span><span class=\"nc-red nc-bold\">prématurité</span></span>, <span><span class=\"nc-red nc-bold\">faible poids de naissance</span></span>, <span><span class=\"nc-red nc-bold\">mortalité</span></span><span class=\"nc-red nc-bold\"> périnatale</span>.\n            </td>\n            <td>\n              <span>Pas de supplémentation sauf anémie</span> : Hb <span><span class=\"nc-pink nc-bold\">&lt; 11 g/dL</span></span> (T1-T2), <span>&lt; <span class=\"nc-pink nc-bold\">10,5 g/dL</span></span> (T3) ou <span>ferritine</span> <span>&lt; 12</span> → <span>50 mg/j de <span class=\"nc-blue_bg\">fer</span> métal</span> (prise <strong><span>1 j</span>/2</strong> plus efficace).\n              <strong><span>NFS</span> systématique à <span>M6</span></strong> (dès le T1 si FDR) ; électrophorèse de l'<span>hémoglobine</span> selon l'origine géographique.\n            </td>\n          </tr>\n          <tr>\n            <td><span><strong>Vitamine D</strong></span><br><span>supplémentation systématique</span></td>\n            <td>\n              Besoins <span>10 µg/j</span> (<span>1 µg = 40 UI</span>) : 1/3 par l'alimentation, 2/3 par la peau (soleil) ; ↗ absorption intestinale.\n              Constitue les <span>réserves du nouveau-né</span> (minéralisation osseuse).\n              Risques maternels : <span><span class=\"nc-orange_bg\">diabète gestationnel</span></span>, <span><span class=\"nc-orange_bg\">prééclampsie</span></span> ; risques enfant : <span class=\"nc-red_bg\">prématurité</span>, RCIU, <span><span class=\"nc-red_bg\">obésité</span></span>, <span><span class=\"nc-red_bg\">allergie</span></span>.\n            </td>\n            <td>\n              <span>Dose unique de 100 000 UI à M7</span> (fin T2) — <strong>SYSTÉMATIQUE</strong>, pour prévenir les <span>hypocalcémies néonatales</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><span><strong>Calcium</strong></span><br><span>pas de supplémentation</span></td>\n            <td>\n              Nécessaire au <span>squelette fœtal</span> (<span><span class=\"nc-pink nc-bold\">30 g</span></span> de Ca + <span><span class=\"nc-pink nc-bold\">15 g</span></span> de phosphore à terme) ; ↗ absorption intestinale (<span>600 mg/j</span> au T3).\n              En lactation, mobilisation des réserves osseuses.\n              Besoins : <span>700 mg – 1,2 g/j</span> (idéalement &gt; <span>1000 mg</span>/j).\n              Risque : <span>hypocalcémie néonatale</span>, <span>rachitisme</span>.\n            </td>\n            <td>\n              <span>Pas de supplémentation</span> : <strong>produits laitiers <span>3-4/j</span></strong> + <span class=\"nc-pink_bg\">eaux minérales</span> calciques.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Autres carences à connaître : <span>iode</span> (besoins <span <span=\"\">&gt;250</span> µg/j, supplémentation 150 µg/j si carence avérée) et <span>vitamine K</span> PO dès 36 SA chez les femmes sous inducteur enzymatique/<span class=\"nc-pink nc-bold\">antituberculeux</span> (prévention de l'<span class=\"nc-red nc-bold\">hémorragie intracrânienne néonatale</span>).</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":0},{"id":"254-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prévention de la listériose et la toxoplasmose chez la femme non immunisée","contenu":"<div class=\"notion-course\"><p>Deux infections d'origine alimentaire à <strong>prévention essentiellement hygiéno-diététique</strong>. La <span>toxoplasmose</span> ne concerne que la femme <strong>non immunisée (séronégative)</strong>, chez qui une <span>sérologie IgM mensuelle</span> de <span>surveillance</span> est réalisée.</p>\n      <table>\n        <thead><tr><th></th><th>Listériose</th><th>Toxoplasmose (femme séronégative)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span><strong>Risques</strong></span></td>\n            <td>\n              <span>Méningite</span> maternelle · <span>abcès placentaire</span> ·\n              infection du nouveau-né (forme <span>méningée tardive</span> à <span>1-4 semaines</span>) ·\n              <span>avortement</span> · <span><span class=\"nc-red nc-bold\">accouchement prématuré</span></span>\n            </td>\n            <td>\n              <span>Primo-infection → fœtopathie</span>.\n              Si séronégativité : <span>sérologie IgM mensuelle</span> de <span>surveillance</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span><strong>Prévention</strong></span></td>\n            <td>\n              <ul>\n                <li>Éviter : produits artisanaux, <span>fromages au lait cru &amp; râpés</span>, croûtes de fromage, charcuteries sans recuisson (rillettes, foie gras), <span class=\"nc-red_bg\">poissons fumés</span>, <span class=\"nc-red_bg\">coquillages crus</span>, <span class=\"nc-red_bg\">tarama</span>, <span class=\"nc-red_bg\">surimi</span>, œufs de lompe, légumes crus et herbes aromatiques, graines germées crues, lait cru</li>\n                <li><strong>Bien cuire</strong> viandes et poissons</li>\n                <li>Éviter la manipulation de rongeurs, ruminants, oiseaux</li>\n                <li>Nettoyer le frigo à la javel <span>1×/mois</span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><strong>Lavage des mains fréquent</strong> (et après tout contact avec de la viande crue)</li>\n                <li>Éviter la <span>viande crue ou peu cuite</span></li>\n                <li><strong>Éplucher et laver</strong> fruits, légumes et herbes</li>\n                <li>Éviter le contact avec les <span>chats &amp; leur litière</span></li>\n                <li><strong>Jardiner avec des gants</strong></li>\n                <li>Désinfecter le frigo à l'eau de javel <span>2×/mois</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":0},{"id":"254-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les aliments à risque","contenu":"<div class=\"notion-course\"><div class=\"callout callout-danger\"><strong>Aliments <span>à éviter</span></strong>\n        <ul>\n          <li><span><span class=\"nc-red nc-bold\">Alcool</span></span> (<span>CI absolue</span>) et <span>vitamine A</span> — <span>tératogène</span> : <span class=\"nc-red nc-bold\">foie</span>, polyvitaminiques, <span>rétinoïdes</span></li>\n          <li>Aliments <span>crus</span> : lait, viande, <span class=\"nc-green nc-bold\">poisson</span>, œuf</li>\n          <li>Rillettes, pâtés, foie gras, aliments fumés, abats</li>\n          <li>Poissons prédateurs (<span>requin, thon</span>) — métaux lourds</li>\n          <li>Préparations prêtes à consommer ; produits riches en <span>AG saturés</span> ; sucreries, snacks salés/sucrés ; boissons rafraîchissantes sans <span class=\"nc-red nc-bold\">alcool</span></li>\n          <li>Plantes : <span>fenouil, cannelle, réglisse, ginseng, huiles essentielles</span></li>\n          <li><strong>&gt; 1 aliment à base de <span class=\"nc-blue_bg\">soja</span></strong> (phytoœstrogènes : ↗ cancer <span class=\"nc-red_bg nc-bold\">testicule</span>/<span class=\"nc-red_bg nc-bold\">sein</span>, ↘ absorption d'<span class=\"nc-red_bg nc-bold\">iode</span> → pas plus d'<span>1 mg</span>/kg)</li>\n          <li>Margarine et yaourts <span>enrichis en phytostérols</span> (↘ β-carotènes du nourrisson allaité)</li>\n          <li><span>Boissons énergisantes</span> (caféine → risque de <span class=\"nc-red_bg\">retard de croissance</span> fœtal)</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\"><strong>À limiter</strong>\n        <ul>\n          <li><span>Café / thé</span> : <span>2 à 3 tasses/jour</span> maximum (consommation raisonnable autorisée)</li>\n          <li>Charcuterie (boudin noir) ; graisses d'origine animale</li>\n        </ul>\n      </div>\n      <p><strong>À privilégier</strong></p>\n      <ul>\n        <li><span>Fruits et légumes</span> : <span>500 g/jour</span> (éviter les préparations prêtes à consommer, moins riches en nutriments) :\n          <ul>\n            <li>riches en <span>B9</span> : épinards, asperges, salades, choux de Bruxelles, choux-fleurs, brocolis, céleri-rave, betteraves rouges</li>\n            <li>riches en <span>β-carotène</span> : carottes, patates douces, épinards, potirons, choux, salades, melon, tomates, abricots</li>\n            <li>riches en <span>vitamine C</span> : cassis, kiwis, fraises, oranges, ananas, pamplemousses, poivrons, brocolis, choux</li>\n          </ul>\n        </li>\n        <li><span>Légumineuses</span> (lentilles, haricots, pois) et féculents ; produits céréaliers / pain complets</li>\n        <li><span>Lait et produits laitiers</span> écrémés ou demi-écrémés</li>\n        <li><span>Viande</span> peu grasse et riche en fer ; <span>œuf</span></li>\n        <li><span>Poissons</span> : <span>2×/semaine</span>, dont un <span class=\"nc-green nc-bold\">poisson</span> gras (AG polyinsaturés) — varier espèces et approvisionnement (contamination par <span class=\"nc-blue nc-bold\">dioxines</span>), limiter les prédateurs sauvages</li>\n        <li><span>Eau</span> : boire <strong><span <span=\"\">&gt;1</span> litre de plus</strong></li>\n      </ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":0}],"astuces":[{"type":"warn","titre":"Folates : ne pas confondre les fenêtres","contenu":"<p><strong>Supplémentation systématique <span class=\"kw-ttt\">0,4 mg/j</span> = <span class=\"kw-chiffre\">28 j avant conception → 12 SA</span></strong> (LiSA). Le tube neural se referme <strong>avant S3</strong> — supplémenter <span class=\"kw-alerte\">après la découverte de grossesse est trop tard</span> pour prévenir un spina-bifida. <strong>Haut risque (× 10 = <span class=\"kw-ttt\">4-5 mg/j</span>)</strong> : <span class=\"kw-etio\">épilepsie</span> sous anticonvulsivants, <span class=\"kw-etio\">IMC &gt; 28</span>, <span class=\"kw-etio\">ATCD de dysraphie</span> + vit B6/B12.</p>"},{"type":"warn","titre":"Fer et vitamine D : 2 logiques opposées","contenu":"<p><span class=\"kw-def\">Fer</span> = <strong>PAS de supplémentation systématique</strong> — seulement si <span class=\"kw-bio\">Hb &lt; 11 g/dL</span> (T1-T2) ou <span class=\"kw-chiffre\">&lt; 10,5 g/dL</span> (T3) ou <span class=\"kw-bio\">ferritine &lt; 12</span> (<span class=\"kw-ttt\">50 mg/j de fer métal</span>, prise <strong>1 j/2 plus efficace</strong>). <span class=\"kw-def\">Vitamine D</span> = <strong>SYSTÉMATIQUE</strong> à la fin du T2 : <span class=\"kw-ttt\">100 000 UI PO en dose unique à M7</span>. <span class=\"kw-def\">Calcium</span> = pas de supplémentation médicamenteuse — cible <strong>&gt; 1000 mg/j</strong> par <span class=\"kw-clinique\">3-4 produits laitiers/j</span>.</p>"},{"type":"tip","titre":"Prise de poids — repère IMC","contenu":"<p><strong>« <span class=\"kw-chiffre\">18 · 16 · 11,5 · 9</span> »</strong> = borne <span class=\"kw-alerte\">haute</span> de prise de poids selon IMC pré-conceptionnel (<span class=\"kw-chiffre\">&lt;18,5</span> · <span class=\"kw-chiffre\">normal</span> · <span class=\"kw-chiffre\">surpoids</span> · <span class=\"kw-chiffre\">obèse</span>). Prise de poids <span class=\"kw-alerte\">excessive</span> → risque <span class=\"kw-etio\">diabète gestationnel</span>, <span class=\"kw-etio\">HTA gravidique</span>, <span class=\"kw-etio\">macrosomie</span>, <span class=\"kw-etio\">césarienne</span>. Prise de poids <span class=\"kw-alerte\">insuffisante</span> → <span class=\"kw-etio\">MAP</span> et <span class=\"kw-etio\">faible poids de naissance</span>.</p>"},{"type":"warn","titre":"Listeria vs Toxoplasmose — le geste qui trie","contenu":"<p><strong><span class=\"kw-clinique\">Listériose</span></strong> = attention aux <strong>produits laitiers/charcuteries prêts à consommer</strong> (fromages au lait cru, croûtes, rillettes, poissons fumés) → <strong>cuisson</strong> et éviction. <strong><span class=\"kw-clinique\">Toxoplasmose</span> (femme séronégative)</strong> = attention à la <strong>terre et aux chats</strong> → <strong>lavage soigneux des crudités</strong>, gants au jardinage, éviter litière. Une <span class=\"kw-bio\">sérologie IgM mensuelle</span> chez la séronégative.</p>"}],"strategie":{"principes":"<p><strong>Grossesse ≠ « manger pour 2 ».</strong> Surcoût énergétique modéré et progressif (<span class=\"kw-chiffre\">+70/+260/+500 kcal/j</span> T1/T2/T3) couvert spontanément par l'appétit. <strong>Plancher <span class=\"kw-chiffre\">1600 kcal/j</span></strong> (en dessous : <span class=\"kw-alerte\">corps cétoniques</span> délétères pour le développement cérébral fœtal).</p>\n    <p><strong>3 axes de supplémentation à mémoriser :</strong></p>\n    <ul>\n      <li><span class=\"kw-def\">Folates (B9)</span> : <span class=\"kw-ttt\">0,4 mg/j</span> de <span class=\"kw-chiffre\">−28 j</span> à <span class=\"kw-chiffre\">12 SA</span> — <span class=\"kw-alerte\">systématique</span> (× 10 si haut risque)</li>\n      <li><span class=\"kw-def\">Vitamine D</span> : <span class=\"kw-ttt\">100 000 UI PO</span> à <span class=\"kw-chiffre\">M7</span> — <span class=\"kw-alerte\">systématique</span></li>\n      <li><span class=\"kw-def\">Fer</span> : <span class=\"kw-alerte\">jamais systématique</span> — uniquement si anémie prouvée (NFS à M6)</li>\n    </ul>\n    <p><strong>Alimentation :</strong> variée, fractionnée (3-5 repas/j), hydratation <span class=\"kw-chiffre\">2,3-2,5 L/j</span>. <span class=\"kw-ci\">CI absolue à l'alcool</span>. Prévention hygiéno-diététique <span class=\"kw-etio\">listériose</span> et <span class=\"kw-etio\">toxoplasmose</span> (si séronégative). Éviction : soja &gt; 1/j (phytoœstrogènes), phytostérols, prédateurs marins (méthyl-mercure).</p>\n    <p><strong>Populations à risque :</strong> adolescentes, précarité, grossesses gémellaires/rapprochées, TCA, régimes restrictifs, tabac/alcool/toxico, ATCD de dysraphie, ATCD de chirurgie bariatrique (carences ++).</p>","suivi":"<p><strong>Prise de poids :</strong> cible selon IMC pré-conceptionnel (<span class=\"kw-chiffre\">5-9 kg</span> si obésité → <span class=\"kw-chiffre\">12,5-18 kg</span> si maigreur). Surveillance à chaque consultation prénatale.<br><strong>Biologie :</strong> <span class=\"kw-bio\">NFS systématique à M6</span> (ou dès T1 si FDR), électrophorèse de l'Hb selon origine géographique. <span class=\"kw-bio\">Sérologie toxoplasmose IgM mensuelle</span> chez la séronégative.<br><strong>Éducation :</strong> conseils hygiéno-diététiques répétés, dépistage précoce des carences et du <span class=\"kw-etio\">diabète gestationnel</span>.</p>","redflags":"<ul>\n      <li><span class=\"kw-alerte\">Prise de poids &gt; borne haute</span> : dépister <span class=\"kw-etio\">diabète gestationnel</span> et <span class=\"kw-etio\">HTA gravidique</span></li>\n      <li><span class=\"kw-alerte\">Prise de poids insuffisante</span> ou apports &lt; <span class=\"kw-chiffre\">1600 kcal/j</span> : risque <span class=\"kw-etio\">MAP</span>, <span class=\"kw-etio\">RCIU</span>, <span class=\"kw-etio\">faible poids de naissance</span></li>\n      <li><span class=\"kw-alerte\">Signes d'anémie</span> (asthénie, pâleur, dyspnée) → NFS/ferritine sans délai</li>\n      <li><span class=\"kw-alerte\">Syndrome fébrile</span> chez femme enceinte : évoquer <span class=\"kw-etio\">listériose</span> (hémocultures + traitement empirique) — <span class=\"kw-alerte\">urgence obstétricale</span></li>\n    </ul>"},"cards":[{"i":"942a7bd79dd9","n":254,"o":"254-1","u":"Physiopathologie","t":"Connaître les besoins nutritionnels de la femme enceinte","q":"Que retenir concernant les besoins nutritionnels de la femme enceinte ?","a":"<div class=\"notion-course\"><p>La <span><span class=\"nc-brown_bg\">grossesse</span></span> <strong>n'impose pas de « manger pour deux »</strong> : il ne faut <span>pas augmenter volontairement les apports</span>. Les besoins énergétiques n'<span class=\"nc-green nc-bold\">augmentent</span> que modérément, et de façon progressive selon le trimestre.</p>\n      <div class=\"callout callout-danger\"><strong>Apport énergétique global : <span>1600 kcal/j minimum</span>.</strong> En dessous de ce seuil, production de <span>corps cétoniques</span> — délétère pour le <span>développement cérébral du fœtus</span> (risque de <span>RCIU</span> et de <span><span class=\"nc-red nc-bold\">faible poids de naissance</span></span>).</div>\n      <p><strong>Surcoût énergétique par trimestre</strong> (à ne pas rechercher activement, l'appétit s'adapte spontanément) :</p>\n      <table>\n        <thead><tr><th>Trimestre</th><th>Surcoût énergétique</th></tr></thead>\n        <tbody>\n          <tr><td><span><strong>T1</strong></span></td><td><span>+ 70 kcal/j</span> (faible)</td></tr>\n          <tr><td><span><strong>T2</strong></span></td><td><span>+ 260 kcal/j</span></td></tr>\n          <tr><td><span><strong>T3</strong></span></td><td><span>+ 500 kcal/j</span> (maximal)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Répartition des macronutriments</strong> — en proportion de l'apport énergétique total, elle reste <strong>identique à la population générale</strong> (seule exception : seuil minimal des protéines au T3 = <span>12 %</span>).</p>\n      <ul>\n        <li><span>Glucides</span> (<span>50-55 %</span>) : besoins ↗ de <span>130 → 175 g/j</span></li>\n        <li><span>Protides</span> (<span>15-20 %</span>) : besoins ↗ jusqu'à <span>70 g/j</span></li>\n        <li><span>Lipides</span> (<span>30 %</span>) : <strong>pas de modification</strong> des besoins</li>\n      </ul>\n      <p><strong>Une alimentation variée et fractionnée</strong></p>\n      <ul>\n        <li><span>Produits laitiers</span> (calcium), <span>fruits et légumes frais</span> (vitamines)</li>\n        <li>Repas <strong>fractionnés</strong> : <span>3 à 5×/jour</span></li>\n        <li><span>Poisson</span> <span>3×/semaine</span> — éviter espadon et maquereau (<span>métaux lourds</span>), éviter saumon sauvage, <strong>varier les lieux d'approvisionnement</strong></li>\n        <li>Privilégier les aliments riches en <span>B9</span>, <span>β-carotène</span> et <span>vitamine C</span></li>\n        <li>Limiter le <span><span class=\"nc-blue_bg\">soja</span></span> (<strong><span>≤ 1/jour</span></strong>) ; <span class=\"nc-red nc-bold\">margarine enrichie</span> en phytostérols <strong>déconseillée</strong></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Apports hydriques.</strong> Besoins <strong>augmentés</strong> : <span><span class=\"nc-pink nc-bold\">2,3-2,5 L</span>/j</span>. <span>CI absolue à l'<span class=\"nc-red nc-bold\">alcool</span>.</span> Pas de <span class=\"nc-red nc-bold\">boissons gazeuses</span>/sodas ; éviter les <span class=\"nc-red nc-bold\">boissons riches en sel</span> ; limiter les <span class=\"nc-red\">excitants</span> (<span><span class=\"nc-red nc-bold\">café</span>, <span class=\"nc-red nc-bold\">thé</span></span>).</div>\n      <div class=\"callout callout-warn\"><strong>Les 1000 premiers jours (programmation).</strong> De la <strong>conception à<span> 2 ans</span></strong> = fenêtre critique de vulnérabilité à l'environnement (<span><span class=\"nc-orange\">origine développementale des maladies</span></span>). <span class=\"nc-orange_bg\">Dénutrition</span>, malnutrition ou surnutrition maternelles ↗ le risque d'<span><span class=\"nc-orange_bg\">obésité</span></span>, de <span>diabète</span> et de <span>maladie cardiovasculaire</span> chez l'enfant à l'âge adulte (mécanismes <span>épigénétiques</span>).</div></div>"},{"i":"a71ad4f8d32b","n":254,"o":"254-2","u":"Physiopathologie","t":"Connaître la prise de poids attendue pendant la grossesse","q":"Que retenir concernant la prise de poids attendue pendant la grossesse ?","a":"<div class=\"notion-course\"><p>La prise de poids associe <span>poids du <span class=\"nc-green nc-bold\">fœtus</span></span>, <span><span class=\"nc-green nc-bold\">placenta</span></span>, <span><span class=\"nc-green nc-bold\">liquide amniotique</span></span> et <span>accumulation de graisse</span> maternelle. Elle est <strong>faible au T1</strong>, puis <strong>marquée aux T2 et T3</strong>, et <strong>influencée par l'IMC pré-<span><span class=\"nc-brown_bg\">grossesse</span></span></strong>. En moyenne <span>≈ <span class=\"nc-pink nc-bold\">13 kg</span></span> (variations possibles : <span>œdèmes</span>, durée de <span class=\"nc-brown_bg\">grossesse</span>, gémellité).</p>\n      <div class=\"callout callout-info\"><strong>Repères pratiques.</strong> <span>≈ 1 kg/mois</span> du T1 au T3, et <span>500 g/semaine</span> au T3.</div>\n      <p><strong>Gain pondéral recommandé selon l'IMC pré-conceptionnel</strong></p>\n      <table>\n        <thead><tr><th>IMC pré-conceptionnel</th><th>Gain total recommandé</th><th>Taux moyen T2-T3</th></tr></thead>\n        <tbody>\n          <tr><td><span>Maigreur</span> (&lt; 18,5)</td><td><span>12,5 – 18 kg</span></td><td><span>0,5 kg/sem</span></td></tr>\n          <tr><td><span>Normal</span> (18,5 – 24,9)</td><td><span>11,5 – 16 kg</span></td><td><span>0,4 kg/sem</span></td></tr>\n          <tr><td><span>Surpoids</span> (25 – 29,9)</td><td><span>7 – 11,5 kg</span></td><td><span>0,3 kg/sem</span></td></tr>\n          <tr><td><span>Obésité</span> (<span>≥ 30</span>)</td><td><span>5 – 9 kg</span></td><td><span>0,2 kg/sem</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"nc-red_bg\">Prise de poids excessive</span>.</strong> Risque de <span><span class=\"nc-orange_bg\">diabète gestationnel</span></span>, de <span><span class=\"nc-red nc-bold\">HTA gravidique</span></span>, de <span><span class=\"nc-red nc-bold\">macrosomie</span></span> et de <span><span class=\"nc-red nc-bold\">césarienne</span></span> (surcharge pondérale).</div>\n      <div class=\"callout callout-warn\"><strong><span class=\"nc-red_bg\">Prise de poids insuffisante</span>.</strong> Risque de <span>menace d'<span class=\"nc-red nc-bold\">accouchement prématuré</span> (MAP)</span> et de <span><span class=\"nc-red nc-bold\">faible poids de naissance</span></span>.</div>\n      <p class=\"muted\" style=\"margin:6px 0 0\"><em>Un poids de naissance &lt; <span>2500 g</span> ou &gt; <span>4000 g</span> est un FDR ultérieur d'<span><span class=\"nc-orange_bg\">obésité</span></span> et de <span><span class=\"nc-orange_bg\">syndrome métabolique</span></span> chez l'enfant.</em></p></div>"},{"i":"eb50d0bbc1d2","n":254,"o":"254-3","u":"Physiopathologie","t":"Connaître la prévention du spina-bifida","q":"Que retenir concernant la prévention du spina-bifida ?","a":"<div class=\"notion-course\"><ul><li>La fermeture du tube neural se déroule très tôt, pendant les premières semaines après la conception, souvent avant la découverte de la grossesse. La prévention doit donc commencer avant la conception.</li><li>Acide folique 400 µg/j en prévention courante : idéalement au moins quatre semaines avant la conception et jusqu’à douze SA. Une alimentation riche en folates complète, sans remplacer, cette supplémentation.</li><li>Chez certaines femmes à haut risque, notamment antécédent d’anomalie de fermeture du tube neural, une dose élevée sur prescription est indiquée ; vérifier les facteurs et le schéma avec l’équipe.</li><li>Un traitement antiépileptique potentiellement tératogène nécessite une consultation préconceptionnelle ; ne pas l’arrêter brutalement et ne pas considérer que les folates annulent sa tératogénicité.</li></ul></div>"},{"i":"87f7a7c6d7ca","n":254,"o":"254-4","u":"Diagnostic positif","t":"Connaître les populations à risque nutritionnel pendant la grossesse","q":"Que retenir concernant les populations à risque nutritionnel pendant la grossesse ?","a":"<div class=\"notion-course\"><p>Repérer ces situations à l'interrogatoire permet de <strong>cibler la <span>surveillance</span> et les supplémentations</strong>. Les axes prioritaires de carence à surveiller sont : <span>fer</span>, <span>acide folique</span>, <span>vitamine D</span>, <span>calcium</span>, <span><span class=\"nc-red_bg nc-bold\">iode</span></span> et le <span>risque infectieux</span>.</p>\n      <p><strong><span>Facteurs de risque</span> nutritionnel</strong></p>\n      <ul>\n        <li><span>Adolescentes</span> (croissance non terminée)</li>\n        <li><span>Bas niveau socio-économique et éducatif</span>, précarité</li>\n        <li><span><span class=\"nc-green nc-bold\">Grossesses rapprochées</span></span></li>\n        <li><span>Grossesses multiples</span></li>\n        <li><span>Intoxication alcoolo-tabagique</span>, toxicomanie</li>\n        <li><span>ATCD d'anomalie de fermeture du tube neural</span> ou de fente labio-palatine ; maladies chroniques</li>\n        <li><span>Régimes restrictifs, déséquilibrés</span> (végétarien/végétalien), <span>TCA</span></li>\n        <li><span>Excès pondéral</span>, <span>diabète</span></li>\n      </ul>\n      <p><strong>Situations spécifiques nécessitant une adaptation</strong></p>\n      <table>\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><span><strong>Vomissements du T1</strong></span></td><td><strong>Fractionner</strong> les repas</td></tr>\n          <tr><td><span><strong><span class=\"nc-orange_bg\">Diabète gestationnel</span></strong></span></td><td>Manger équilibré, <span>sans régime restrictif</span></td></tr>\n          <tr><td><span><strong>ATCD chirurgie bariatrique</strong></span></td><td>Risque de <span>carences</span> — <span>surveillance</span> ++</td></tr>\n          <tr><td><span><strong>Obésité</strong></span></td><td>Risque de carences en <span>micronutriments</span></td></tr>\n          <tr><td><span><strong>Adolescente</strong></span> (croissance non finie)</td><td>↗ perte osseuse (<span>grossesse</span> + allaitement) → <strong>compensation calcique</strong></td></tr>\n        </tbody>\n      </table></div>"},{"i":"904c7d062a00","n":254,"o":"254-5","u":"Prise en charge","t":"Connaître les modalités de prévention de la carence en fer, en vitamine D et en calcium","q":"Que retenir concernant les modalités de prévention de la carence en fer, en vitamine D et en calcium ?","a":"<div class=\"notion-course\"><div class=\"callout callout-info\"><strong>Principe clé.</strong> Sur ces trois micronutriments, <strong>une seule supplémentation est systématique : la <span>vitamine D</span> au T3</strong>. Le <span><span class=\"nc-blue_bg\">fer</span></span> et le <span>calcium</span> ne se supplémentent <span>qu'en cas de carence avérée</span> ; le calcium reste couvert par l'alimentation.</div>\n      <table>\n        <thead><tr><th>Micronutriment</th><th><span>Physiopathologie</span> &amp; risques</th><th>Prévention / traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span><strong>Fer</strong></span><br><span>supplémentation NON systématique</span></td>\n            <td>\n              Besoins totaux ≈ <span>1000 mg</span> : <span>30 %</span> pour le fœtus (développement neuro), <span>70 %</span> pour le <span class=\"nc-green nc-bold\">placenta</span> et la <span>masse</span> globulaire maternelle ; ↗ absorption intestinale pour compenser.\n              Carence : <span>25 %</span> des femmes enceintes (pays développés), <span>50 %</span> dans les PED.\n              FDR : <span class=\"nc-brown_bg\">grossesses</span> gémellaires/<span class=\"nc-brown_bg nc-bold\">rapprochées</span>, <span class=\"nc-orange_bg\">ATCD de carence martiale</span>, <span class=\"nc-orange_bg\">régime végétarien</span>, <span class=\"nc-orange_bg\">dénutrition</span>, précarité.\n              Risque : <span><span class=\"nc-red nc-bold\">prématurité</span></span>, <span><span class=\"nc-red nc-bold\">faible poids de naissance</span></span>, <span><span class=\"nc-red nc-bold\">mortalité</span></span><span class=\"nc-red nc-bold\"> périnatale</span>.\n            </td>\n            <td>\n              <span>Pas de supplémentation sauf anémie</span> : Hb <span><span class=\"nc-pink nc-bold\">&lt; 11 g/dL</span></span> (T1-T2), <span>&lt; <span class=\"nc-pink nc-bold\">10,5 g/dL</span></span> (T3) ou <span>ferritine</span> <span>&lt; 12</span> → <span>50 mg/j de <span class=\"nc-blue_bg\">fer</span> métal</span> (prise <strong><span>1 j</span>/2</strong> plus efficace).\n              <strong><span>NFS</span> systématique à <span>M6</span></strong> (dès le T1 si FDR) ; électrophorèse de l'<span>hémoglobine</span> selon l'origine géographique.\n            </td>\n          </tr>\n          <tr>\n            <td><span><strong>Vitamine D</strong></span><br><span>supplémentation systématique</span></td>\n            <td>\n              Besoins <span>10 µg/j</span> (<span>1 µg = 40 UI</span>) : 1/3 par l'alimentation, 2/3 par la peau (soleil) ; ↗ absorption intestinale.\n              Constitue les <span>réserves du nouveau-né</span> (minéralisation osseuse).\n              Risques maternels : <span><span class=\"nc-orange_bg\">diabète gestationnel</span></span>, <span><span class=\"nc-orange_bg\">prééclampsie</span></span> ; risques enfant : <span class=\"nc-red_bg\">prématurité</span>, RCIU, <span><span class=\"nc-red_bg\">obésité</span></span>, <span><span class=\"nc-red_bg\">allergie</span></span>.\n            </td>\n            <td>\n              <span>Dose unique de 100 000 UI à M7</span> (fin T2) — <strong>SYSTÉMATIQUE</strong>, pour prévenir les <span>hypocalcémies néonatales</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><span><strong>Calcium</strong></span><br><span>pas de supplémentation</span></td>\n            <td>\n              Nécessaire au <span>squelette fœtal</span> (<span><span class=\"nc-pink nc-bold\">30 g</span></span> de Ca + <span><span class=\"nc-pink nc-bold\">15 g</span></span> de phosphore à terme) ; ↗ absorption intestinale (<span>600 mg/j</span> au T3).\n              En lactation, mobilisation des réserves osseuses.\n              Besoins : <span>700 mg – 1,2 g/j</span> (idéalement &gt; <span>1000 mg</span>/j).\n              Risque : <span>hypocalcémie néonatale</span>, <span>rachitisme</span>.\n            </td>\n            <td>\n              <span>Pas de supplémentation</span> : <strong>produits laitiers <span>3-4/j</span></strong> + <span class=\"nc-pink_bg\">eaux minérales</span> calciques.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Autres carences à connaître : <span>iode</span> (besoins <span <span=\"\">&gt;250</span> µg/j, supplémentation 150 µg/j si carence avérée) et <span>vitamine K</span> PO dès 36 SA chez les femmes sous inducteur enzymatique/<span class=\"nc-pink nc-bold\">antituberculeux</span> (prévention de l'<span class=\"nc-red nc-bold\">hémorragie intracrânienne néonatale</span>).</em></p></div>"},{"i":"d291a3feb8c2","n":254,"o":"254-6","u":"Prise en charge","t":"Connaître les modalités de prévention de la listériose et la toxoplasmose chez la femme non immunisée","q":"Que retenir concernant les modalités de prévention de la listériose et la toxoplasmose chez la femme non immunisée ?","a":"<div class=\"notion-course\"><p>Deux infections d'origine alimentaire à <strong>prévention essentiellement hygiéno-diététique</strong>. La <span>toxoplasmose</span> ne concerne que la femme <strong>non immunisée (séronégative)</strong>, chez qui une <span>sérologie IgM mensuelle</span> de <span>surveillance</span> est réalisée.</p>\n      <table>\n        <thead><tr><th></th><th>Listériose</th><th>Toxoplasmose (femme séronégative)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span><strong>Risques</strong></span></td>\n            <td>\n              <span>Méningite</span> maternelle · <span>abcès placentaire</span> ·\n              infection du nouveau-né (forme <span>méningée tardive</span> à <span>1-4 semaines</span>) ·\n              <span>avortement</span> · <span><span class=\"nc-red nc-bold\">accouchement prématuré</span></span>\n            </td>\n            <td>\n              <span>Primo-infection → fœtopathie</span>.\n              Si séronégativité : <span>sérologie IgM mensuelle</span> de <span>surveillance</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span><strong>Prévention</strong></span></td>\n            <td>\n              <ul>\n                <li>Éviter : produits artisanaux, <span>fromages au lait cru &amp; râpés</span>, croûtes de fromage, charcuteries sans recuisson (rillettes, foie gras), <span class=\"nc-red_bg\">poissons fumés</span>, <span class=\"nc-red_bg\">coquillages crus</span>, <span class=\"nc-red_bg\">tarama</span>, <span class=\"nc-red_bg\">surimi</span>, œufs de lompe, légumes crus et herbes aromatiques, graines germées crues, lait cru</li>\n                <li><strong>Bien cuire</strong> viandes et poissons</li>\n                <li>Éviter la manipulation de rongeurs, ruminants, oiseaux</li>\n                <li>Nettoyer le frigo à la javel <span>1×/mois</span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><strong>Lavage des mains fréquent</strong> (et après tout contact avec de la viande crue)</li>\n                <li>Éviter la <span>viande crue ou peu cuite</span></li>\n                <li><strong>Éplucher et laver</strong> fruits, légumes et herbes</li>\n                <li>Éviter le contact avec les <span>chats &amp; leur litière</span></li>\n                <li><strong>Jardiner avec des gants</strong></li>\n                <li>Désinfecter le frigo à l'eau de javel <span>2×/mois</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table></div>"},{"i":"7ecb61c0bf1c","n":254,"o":"254-7","u":"Prise en charge","t":"Connaître les aliments à risque","q":"Que retenir concernant les aliments à risque ?","a":"<div class=\"notion-course\"><div class=\"callout callout-danger\"><strong>Aliments <span>à éviter</span></strong>\n        <ul>\n          <li><span><span class=\"nc-red nc-bold\">Alcool</span></span> (<span>CI absolue</span>) et <span>vitamine A</span> — <span>tératogène</span> : <span class=\"nc-red nc-bold\">foie</span>, polyvitaminiques, <span>rétinoïdes</span></li>\n          <li>Aliments <span>crus</span> : lait, viande, <span class=\"nc-green nc-bold\">poisson</span>, œuf</li>\n          <li>Rillettes, pâtés, foie gras, aliments fumés, abats</li>\n          <li>Poissons prédateurs (<span>requin, thon</span>) — métaux lourds</li>\n          <li>Préparations prêtes à consommer ; produits riches en <span>AG saturés</span> ; sucreries, snacks salés/sucrés ; boissons rafraîchissantes sans <span class=\"nc-red nc-bold\">alcool</span></li>\n          <li>Plantes : <span>fenouil, cannelle, réglisse, ginseng, huiles essentielles</span></li>\n          <li><strong>&gt; 1 aliment à base de <span class=\"nc-blue_bg\">soja</span></strong> (phytoœstrogènes : ↗ cancer <span class=\"nc-red_bg nc-bold\">testicule</span>/<span class=\"nc-red_bg nc-bold\">sein</span>, ↘ absorption d'<span class=\"nc-red_bg nc-bold\">iode</span> → pas plus d'<span>1 mg</span>/kg)</li>\n          <li>Margarine et yaourts <span>enrichis en phytostérols</span> (↘ β-carotènes du nourrisson allaité)</li>\n          <li><span>Boissons énergisantes</span> (caféine → risque de <span class=\"nc-red_bg\">retard de croissance</span> fœtal)</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\"><strong>À limiter</strong>\n        <ul>\n          <li><span>Café / thé</span> : <span>2 à 3 tasses/jour</span> maximum (consommation raisonnable autorisée)</li>\n          <li>Charcuterie (boudin noir) ; graisses d'origine animale</li>\n        </ul>\n      </div>\n      <p><strong>À privilégier</strong></p>\n      <ul>\n        <li><span>Fruits et légumes</span> : <span>500 g/jour</span> (éviter les préparations prêtes à consommer, moins riches en nutriments) :\n          <ul>\n            <li>riches en <span>B9</span> : épinards, asperges, salades, choux de Bruxelles, choux-fleurs, brocolis, céleri-rave, betteraves rouges</li>\n            <li>riches en <span>β-carotène</span> : carottes, patates douces, épinards, potirons, choux, salades, melon, tomates, abricots</li>\n            <li>riches en <span>vitamine C</span> : cassis, kiwis, fraises, oranges, ananas, pamplemousses, poivrons, brocolis, choux</li>\n          </ul>\n        </li>\n        <li><span>Légumineuses</span> (lentilles, haricots, pois) et féculents ; produits céréaliers / pain complets</li>\n        <li><span>Lait et produits laitiers</span> écrémés ou demi-écrémés</li>\n        <li><span>Viande</span> peu grasse et riche en fer ; <span>œuf</span></li>\n        <li><span>Poissons</span> : <span>2×/semaine</span>, dont un <span class=\"nc-green nc-bold\">poisson</span> gras (AG polyinsaturés) — varier espèces et approvisionnement (contamination par <span class=\"nc-blue nc-bold\">dioxines</span>), limiter les prédateurs sauvages</li>\n        <li><span>Eau</span> : boire <strong><span <span=\"\">&gt;1</span> litre de plus</strong></li>\n      </ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181a59852d07fa270e427?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"liensGlobaux":[{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Situation nutritionnelle à risque ?","detail":"<ul><li>IMC, trajectoire pondérale, restrictions, précarité, malabsorption et antécédents.</li></ul>","branches":[{"label":"Oui","to":"adapte"},{"label":"Non","to":"prevention"}]},{"id":"adapte","kind":"decision","label":"Évaluation et accompagnement individualisés","detail":"<ul><li>Éviter restriction excessive et supplémentation non adaptée.</li></ul>","branches":[{"label":"Prévenir les carences","to":"prevention"}]},{"id":"prevention","kind":"decision","label":"Folates et autres besoins","detail":"<ul><li>Folates en préconception/début de grossesse ; fer, vitamine D, calcium selon recommandations et situation.</li></ul>","branches":[{"label":"Sécurité alimentaire","to":"aliments"}]},{"id":"aliments","kind":"decision","label":"Réduire les risques alimentaires","detail":"<ul><li>Hygiène, toxoplasmose/listériose ; éviter alcool, aliments à risque et excès de vitamine A.</li></ul>","branches":[{"label":"Suivi","to":"suivi"}]},{"id":"suivi","kind":"finish","label":"Suivre poids, apports et biologie indiquée","detail":"<ul><li>Adapter aux symptômes, croissance et carences documentées.</li></ul>","branches":[]}]}};
